<script setup>
import {computed} from 'vue';
const props=defineProps({modelValue:Object,companies:{type:Array,default:()=>[]},readonly:Boolean,compact:Boolean});const emit=defineEmits(['update:modelValue']);
const food=computed(()=>props.modelValue);
function set(path,value){const next=JSON.parse(JSON.stringify(food.value));const keys=path.split('.');let obj=next;for(const key of keys.slice(0,-1))obj=obj[key];obj[keys.at(-1)]=value===''?null:value;if(path==='company_name')next.company_id=props.companies.find(c=>c.name===value)?.id||null;emit('update:modelValue',next)}
const attrs={flavor:'맛·종류',origin_region:'산지',size_grade:'크기 구분',quality_grade:'품질 등급',intended_use:'사용 용도',labeling_requirement:'표시 기준',origin_country:'원산지'};
const specs={piece_quantity:'낱개 중량·용량',piece_unit:'낱개 단위',pack_count:'포장 수량',quantity:'전체 중량·용량',unit:'전체 단위',sales_unit:'판매 단위'};
const prices={source_applied:'자료의 적용가',survey_1:'조사가 1',survey_2:'조사가 2',survey_3:'조사가 3'};
const allergens={egg:'난류',milk:'우유',buckwheat:'메밀',peanut:'땅콩',soy:'대두',wheat:'밀',mackerel:'고등어',crab:'게',shrimp:'새우',pork:'돼지고기',peach:'복숭아',tomato:'토마토',sulfite:'아황산류',walnut:'호두',chicken:'닭고기',beef:'쇠고기',squid:'오징어',shellfish:'조개류',pine_nut:'잣'};
const list=value=>(value||[]).map(c=>allergens[c]||c).join(', ');
function allergy(key,event){const values=[...event.target.selectedOptions].map(o=>o.value);set('allergens.'+key,values.length?values:null)}
</script>
<template><div v-if="food" class="food-record-form" :class="{compact}"><p class="small muted">확인되지 않은 항목은 공란으로 남겨 주세요.</p><fieldset :disabled="readonly"><label>식품명<input :value="food.food_name" @input="set('food_name',$event.target.value)" aria-label="표준 식품명"></label><label>업체<input :value="food.company_name" @input="set('company_name',$event.target.value)" list="food-companies" placeholder="업체명 또는 공란" aria-label="업체"><datalist id="food-companies"><option v-for="c in companies" :key="c.id" :value="c.name"/></datalist></label><p v-if="food.raw_food_name" class="original-value">원문 식품명: {{food.raw_food_name}}</p><label>규격 원문<input :value="food.specification.original_text" @input="set('specification.original_text',$event.target.value)" placeholder="예: 100g × 10개 / 1kg"></label><slot/><details :open="!compact"><summary>규격 세부 정보·식품코드 <span v-if="compact">선택 입력</span></summary><p class="small muted">낱개 규격과 전체 규격을 구분합니다. 확인할 수 없는 값은 공란으로 남겨 주세요.</p><div class="two-col"><label v-for="(label,key) in specs" :key="key">{{label}}<input :value="food.specification[key]" @input="set('specification.'+key,$event.target.value)" :aria-label="label"></label></div><p v-if="food.specification.normalized_quantity" class="small muted">환산: {{food.specification.normalized_quantity}} {{food.specification.normalized_unit}}</p><label>공통식품코드<input :value="food.food_code" @input="set('food_code',$event.target.value)" aria-label="공통식품코드"></label></details><details><summary>식품 속성</summary><div class="two-col"><label v-for="(label,key) in attrs" :key="key">{{label}}<input :value="food.attributes[key]" @input="set('attributes.'+key,$event.target.value)"></label></div><label>공통식품속성 원문<textarea :value="food.attributes.original_text" @input="set('attributes.original_text',$event.target.value)" rows="2"/></label><p v-for="i in food.attributes.ingredients" class="small">원재료: {{i.name}} {{i.percentage}}% · {{i.origin_country}}</p><p v-if="food.attributes.other?.length" class="small">기타: {{food.attributes.other.join(' / ')}}</p><label>친환경 구분<input :value="food.eco_classification" @input="set('eco_classification',$event.target.value)"></label><label>업체군<input :value="food.supplier_group" @input="set('supplier_group',$event.target.value)"></label></details><details><summary>알레르기 정보 · {{{unknown:'미확인',source_declared:'원문 표시 있음',reviewed:'표시사항 검토 완료'}[food.allergens.review_status]}}</summary><p class="small muted">공란은 미확인입니다. 식품명·원재료에서 찾은 후보는 함유 확정 정보가 아닙니다.</p><p v-if="food.allergens.candidates.length" class="notice small">확인할 후보: {{list(food.allergens.candidates)}}</p><label v-for="(label,key) in {contains:'원문 함유 표시',may_contain:'같은 시설·혼입 가능 표시',free_from_claims:'원문 불포함 주장'}" :key="key">{{label}}<span v-if="readonly">{{list(food.allergens[key])||'—'}}</span><select v-else multiple :value="food.allergens[key]||[]" @change="allergy(key,$event)"><option v-for="(name,code) in allergens" :value="code">{{name}}</option></select></label><label>알레르기 표시 원문·확인 근거<textarea :value="food.allergens.original_text" @input="set('allergens.original_text',$event.target.value)" rows="2"/></label><label>확인 상태<select :value="food.allergens.review_status" @change="set('allergens.review_status',$event.target.value)"><option value="unknown">미확인</option><option value="source_declared">원문 표시 있음</option><option value="reviewed">표시사항 검토 완료</option></select></label></details><details><summary>자료의 가격 열</summary><p class="small muted">조사가와 자료의 적용가는 실제 공급 단가와 별도로 보관합니다. 공란과 0원을 구별합니다.</p><div class="two-col"><label v-for="(label,key) in prices" :key="key">{{label}}<input :value="food.prices[key]" @input="set('prices.'+key,$event.target.value)" inputmode="decimal"></label></div></details><details v-if="compact"><summary>비고</summary><label>추가 메모<textarea :value="food.note" @input="set('note',$event.target.value)" rows="2"/></label></details><label v-else>비고<textarea :value="food.note" @input="set('note',$event.target.value)" rows="2"/></label></fieldset></div></template>
<style scoped>.food-record-form details{border-top:1px solid #e2e7eb;padding:12px 0}.food-record-form summary{cursor:pointer;font-weight:600;margin-bottom:10px}.food-record-form select[multiple]{min-height:110px}.food-record-form fieldset{margin:0;padding:0;border:0;min-width:0}.food-record-form label>span{display:block;padding:6px 0}.compact>p{margin:0 0 16px;font-size:11px}.compact .original-value{margin:0 0 16px;padding:9px 11px}.compact details{margin:0;border-top:1px solid #e2e9e4;padding:13px 0 2px}.compact summary{font-size:12px;margin-bottom:10px;line-height:1.6}.compact summary>span{font-weight:400;color:#91a096;font-size:10px;margin-left:8px}.compact details[open]{padding-bottom:12px}.compact details label{margin-top:12px}.compact details:not([open]) summary{margin-bottom:0}.compact .change-fields{margin:0 0 16px}.compact fieldset{display:flex;flex-direction:column;gap:0}.compact label{margin-bottom:14px}</style>
